import {ROOMS,PALETTE,COLORS,FLOORS,CATALOG,DEFAULT_STATE,clone,constrain,findPlacement,validateState} from './model.js';
import {HouseWorld} from './world.js';

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const STORAGE='robin-house-design-v1';
let state=clone(DEFAULT_STATE),room=ROOMS.find(r=>r.id==='allrum'),selected=null,mode='overview',history=[],dirty=false,evening=false,photoIndex=0,portal=null,toastTimer,rangeEditing=false,loaded=false;
try{const raw=localStorage.getItem(STORAGE);if(raw){const data=JSON.parse(raw),valid=validateState(data);if(valid){state=valid;room=ROOMS.find(r=>r.id===data.room)||room;loaded=true;}}}catch{}
let world;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
function snapshot(){history.push({state:clone(state),room:room.id});if(history.length>40)history.shift();$('#undo').disabled=false;}
function changed(){dirty=true;$('#save-status').textContent='Du har osparade ändringar.';$('#save').classList.add('unsaved');renderFurniture();}
function applyMutation(fn,{reload=false}={}){snapshot();fn();if(reload){world.load(room,state[room.id],undefined,true);world.evening(evening);if(selected)world.select(selected);}changed();}
function selection(){return state[room.id].objects.find(o=>o.id===selected);}
function openPanel(){if(matchMedia('(max-width:900px)').matches){$('#inspector').classList.add('open');$('#mobile-panel').setAttribute('aria-expanded','true');}}
function closePanel(){$('#inspector').classList.remove('open');$('#mobile-panel').setAttribute('aria-expanded','false');}
function renderRooms(){let html='';for(const floor of [0,1]){html+=`<div class="floor-group">${floor?'Övervåning':'Nedervåning'}</div>`;for(const r of ROOMS.filter(r=>r.floor===floor))html+=`<button class="room-button ${room.id===r.id?'active':''}" data-room="${r.id}" aria-current="${room.id===r.id?'location':'false'}"><img src="./photos/${r.photos[0]}.jpg" alt="" loading="lazy"><span>${r.name}</span>${icon('chevron')}</button>`;}$('#room-list').innerHTML=html;$('#room-count').textContent=ROOMS.length+' rum';$$('[data-room]').forEach(btn=>btn.onclick=()=>goRoom(btn.dataset.room));}
function renderSurfaces(){$('#wall-name').textContent=PALETTE.find(c=>c[0]===state[room.id].wall)?.[1]||'Egen nyans';$('#wall-custom').value=state[room.id].wall;$('#wall-swatches').innerHTML=PALETTE.map(([color,name])=>`<button class="swatch ${color===state[room.id].wall?'active':''}" data-wall="${color}" style="--color:${color};--check:${color==='#4b5454'?'#ffffff':'#24352a'}" title="${name}" aria-label="Måla väggarna ${name.toLowerCase()}" aria-pressed="${color===state[room.id].wall}"></button>`).join('');$$('[data-wall]').forEach(btn=>btn.onclick=()=>{applyMutation(()=>{state[room.id].wall=btn.dataset.wall;world.paint(btn.dataset.wall);});renderSurfaces();});$('#floor-options').innerHTML=FLOORS.map(([id,name])=>`<button class="floor-button ${state[room.id].flooring===id?'active':''}" data-floor="${id}" aria-pressed="${state[room.id].flooring===id}"><span class="floor-sample"></span><span>${name}</span></button>`).join('');$$('[data-floor]').forEach(btn=>btn.onclick=()=>{applyMutation(()=>{state[room.id].flooring=btn.dataset.floor;},{reload:true});renderSurfaces();});}
function renderFurniture(){$('#furniture-list').innerHTML=state[room.id].objects.map(o=>`<button class="furniture-row ${selected===o.id?'active':''}" data-object="${o.id}" aria-pressed="${selected===o.id}"><span class="object-dot" style="--color:${o.color}"></span><span>${CATALOG[o.type].name}</span>${icon('chevron')}</button>`).join('');if(!state[room.id].objects.length)$('#furniture-list').innerHTML='<p class="muted">Rummet är tomt. Lägg till din första möbel med plusknappen.</p>';$$('[data-object]').forEach(btn=>btn.onclick=()=>selectObject(btn.dataset.object));}
function selectObject(id,showPanel=true){selected=id;world.select(id);renderFurniture();renderSelection();if(id&&showPanel)openPanel();}
function renderSelection(){const obj=selection(),container=$('#selection-editor');if(!obj){container.hidden=true;container.innerHTML='';return;}const c=CATALOG[obj.type];container.hidden=false;container.innerHTML=`<div class="selection-card"><div class="selection-heading"><h3>${c.name}</h3><button id="deselect" class="icon-button" aria-label="Avmarkera möbel">${icon('close')}</button></div><div class="swatches">${COLORS.map(color=>`<button class="swatch ${obj.color===color?'active':''}" data-object-color="${color}" style="--color:${color}" aria-label="Möbelfärg ${color}" aria-pressed="${obj.color===color}"></button>`).join('')}</div><label class="custom-color">Egen möbelfärg<input id="object-color" type="color" value="${obj.color}" aria-label="Välj möbelns färg"></label>${c.fixed?'<p class="muted">Fast inredning. Du kan prova olika färger.</p>':`<div class="selection-actions"><button id="rotate">${icon('rotate')}Rotera</button><button id="remove">${icon('trash')}Ta bort</button></div><div class="range-label"><span>Flytta på golvet</span><span>10 cm</span></div><div class="nudge-row"><button data-nudge="0,-0.1" aria-label="Flytta mot rummets bortre vägg">↑</button><button data-nudge="-0.1,0" aria-label="Flytta åt vänster">←</button><button data-nudge="0.1,0" aria-label="Flytta åt höger">→</button><button data-nudge="0,0.1" aria-label="Flytta mot rummets främre vägg">↓</button></div><label class="range-label" for="scale"><span>Storlek</span><span id="scale-value">${Math.round(obj.scale*100)} %</span></label><input id="scale" type="range" min="65" max="135" value="${Math.round(obj.scale*100)}" step="5"><p class="muted">${mode==='edit'?'Dra möbeln över golvet för att flytta den.':'Välj Inred för att dra möbeln över golvet.'}</p>`}</div>`;
 $('#deselect').onclick=()=>selectObject(null);$$('[data-object-color]').forEach(btn=>btn.onclick=()=>{applyMutation(()=>{obj.color=btn.dataset.objectColor;world.updateObject(obj,true);});renderSelection();});$('#object-color').onchange=e=>{applyMutation(()=>{obj.color=e.target.value;world.updateObject(obj,true);});renderSelection();};
 if(c.fixed)return;$('#rotate').onclick=rotate;$('#remove').onclick=remove;$$('[data-nudge]').forEach(btn=>btn.onclick=()=>{applyMutation(()=>{const [x,z]=btn.dataset.nudge.split(',').map(Number);obj.x+=x;obj.z+=z;constrain(obj,room);world.updateObject(obj);});});$('#scale').oninput=e=>{if(!rangeEditing){snapshot();rangeEditing=true;}obj.scale=Number(e.target.value)/100;constrain(obj,room);world.updateObject(obj);$('#scale-value').textContent=Math.round(obj.scale*100)+' %';};$('#scale').onchange=()=>{rangeEditing=false;changed();};
}
function rotate(){const obj=selection();if(!obj||CATALOG[obj.type].fixed)return;applyMutation(()=>{obj.rotation=(obj.rotation+Math.PI/4)%(Math.PI*2);constrain(obj,room);world.updateObject(obj);});}
function remove(){const obj=selection();if(!obj||CATALOG[obj.type].fixed)return;applyMutation(()=>{state[room.id].objects=state[room.id].objects.filter(o=>o.id!==obj.id);world.state=state[room.id];world.removeObject(obj.id);selected=null;});renderSelection();toast('Möbeln är borttagen. Du kan ångra.');}
function setPortal(next){if(portal?.to===next?.to)return;portal=next;$('#portal-hint').hidden=!next;if(next){const r=ROOMS.find(r=>r.id===next.to);$('#enter-room').textContent=(next.label||'Till '+r.name)+' →';}}
function goRoom(id){const next=ROOMS.find(r=>r.id===id);if(!next||next.id===room.id)return;const from=room.id;room=next;selected=null;closePanel();world.load(room,state[room.id],from);world.evening(evening);refresh();}
function setMode(next){if(mode===next)return;mode=next;world.setMode(mode);$('#workspace').classList.toggle('walk',mode==='walk');$('#joystick').hidden=mode!=='walk';$('#walk-hint').hidden=mode!=='walk';$$('[data-mode]').forEach(btn=>{const active=btn.dataset.mode===mode;btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',String(active));});$('#scene-sub').textContent=mode==='edit'?'Välj en möbel · Dra för att flytta':'Dra för att vrida · Nyp för att zooma';renderSelection();if(mode==='walk'){closePanel();toast('Gå med styrspaken eller WASD. Dra för att titta.');}else if(mode==='edit'&&!selected)toast('Tryck på en möbel för att börja inreda.');}
function refresh(){$('#floor-name').textContent=room.floor?'ÖVERVÅNING':'NEDERVÅNING';$('#room-name').textContent=room.name;$('#reference-img').src='./photos/'+room.photos[0]+'.jpg';$('#reference-img').alt='Ditt foto av '+room.name.toLowerCase();renderRooms();renderSurfaces();renderFurniture();renderSelection();}
function showPhoto(){const file=room.photos[photoIndex];$('#large-photo').src='./photos/'+file+'.jpg';$('#large-photo').alt='Originalfoto av '+room.name.toLowerCase();$('#photo-title').textContent=room.name;$('#photo-index').textContent=`${photoIndex+1} / ${room.photos.length}`;$('#photo-prev').disabled=room.photos.length<2;$('#photo-next').disabled=room.photos.length<2;}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify({version:1,room:room.id,rooms:state}));dirty=false;$('#save-status').textContent='Sparat i den här webbläsaren.';$('#save').classList.remove('unsaved');toast('Sparat! Dina ändringar finns kvar nästa gång här.');}catch{toast('Det gick inte att spara. Webbläsarens lagring är full eller avstängd.');}}
function undo(){const last=history.pop();if(!last)return;state=last.state;room=ROOMS.find(r=>r.id===last.room);selected=null;world.load(room,state[room.id]);world.evening(evening);changed();refresh();$('#undo').disabled=!history.length;toast('Senaste ändringen är ångrad.');}
function installUI(){
 $$('[data-mode]').forEach(btn=>btn.onclick=()=>setMode(btn.dataset.mode));$('#save').onclick=save;$('#undo').onclick=undo;$('#lighting').onclick=()=>{evening=!evening;world.evening(evening);$('#lighting span').textContent=evening?'Kvällsljus':'Dagsljus';$('#lighting').setAttribute('aria-pressed',String(evening));};$('#center-view').onclick=()=>{if(mode==='walk')world.setMode('walk');else world.center();};$('#help').onclick=()=>$('#help-dialog').showModal();$('#mobile-panel').onclick=()=>$('#inspector').classList.contains('open')?closePanel():openPanel();$('#close-panel').onclick=closePanel();$('#wall-custom').onchange=e=>{applyMutation(()=>{state[room.id].wall=e.target.value;world.paint(e.target.value);});renderSurfaces();};$('#enter-room').onclick=()=>{if(portal)goRoom(portal.to);};$('#reference').onclick=()=>{photoIndex=0;showPhoto();$('#photo-dialog').showModal();};$('#photo-prev').onclick=()=>{photoIndex=(photoIndex-1+room.photos.length)%room.photos.length;showPhoto();};$('#photo-next').onclick=()=>{photoIndex=(photoIndex+1)%room.photos.length;showPhoto();};$$('[data-close]').forEach(btn=>btn.onclick=()=>document.getElementById(btn.dataset.close).close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
 $('#catalog').innerHTML=Object.entries(CATALOG).filter(([,c])=>!c.fixed).map(([type,c])=>`<button data-add="${type}"><span class="catalog-icon" aria-hidden="true">${c.icon}</span><strong>${c.name}</strong><small>${Math.round(c.w*100)} × ${Math.round(c.d*100)} cm</small></button>`).join('');$('#add-furniture').onclick=()=>$('#catalog-dialog').showModal();$$('[data-add]').forEach(btn=>btn.onclick=()=>{const type=btn.dataset.add;if(state[room.id].objects.length>=60){toast('Rummet har många möbler. Ta bort någon innan du lägger till fler.');return;}const place=findPlacement(room,state[room.id].objects,type);if(!place){toast('Möbeln får inte plats. Flytta eller ta bort något först.');return;}const obj={...place,id:crypto.randomUUID(),color:CATALOG[type].color};applyMutation(()=>{state[room.id].objects.push(obj);world.addObject(obj);});$('#catalog-dialog').close();setMode('edit');selectObject(obj.id);toast(CATALOG[type].name+' tillagd.');});
 const joystick=$('#joystick'),stick=$('#stick');let joyId=null;function joyMove(e){const r=joystick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,length=Math.hypot(dx,dy),max=31,scale=length>max?max/length:1;const x=dx*scale,y=dy*scale;world.joy={x:x/max,y:y/max};stick.style.transform=`translate(${x}px,${y}px)`;}joystick.onpointerdown=e=>{joyId=e.pointerId;joystick.setPointerCapture(e.pointerId);joyMove(e);e.preventDefault();};joystick.onpointermove=e=>{if(e.pointerId===joyId)joyMove(e);};const joyEnd=()=>{joyId=null;world.joy={x:0,y:0};stick.style.transform='';};joystick.onpointerup=joyEnd;joystick.onpointercancel=joyEnd;joystick.onlostpointercapture=joyEnd;window.addEventListener('blur',joyEnd);
 window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(e.key==='Escape'){selectObject(null);closePanel();}if(document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.code==='KeyZ'){e.preventDefault();undo();}if((e.ctrlKey||e.metaKey)&&e.code==='KeyS'){e.preventDefault();save();}if(e.code==='KeyR'&&selected){e.preventDefault();rotate();}if(e.code==='KeyE'&&portal)goRoom(portal.to);});
 window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
}
try{world=new HouseWorld($('#scene'),{select:selectObject,beforeChange:snapshot,changed,portal:setPortal});world.load(room,state[room.id]);installUI();refresh();window.houseReady=true;$('#loading').hidden=true;if(loaded)$('#save-status').textContent='Dina sparade ändringar är inlästa.';world.renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('#scene-error').hidden=false;});}catch(error){console.error('Could not start house',error);$('#loading').hidden=true;$('#scene-error').hidden=false;}
